// Normaliza o payload do Typebot SÊNIOR (Closer/Líder) → corpo da Notion API
const out = [];
for (const item of $input.all()) {
  const p = item.json.body ?? item.json;
  const c = p.candidato || {};
  const q = p.qualificacao || {};
  const r = p.respostas_abertas || {};

  const nome = String(c.nome || 'Sem nome').trim();
  const bairroCidade = [c.bairro, c.cidade].filter(Boolean).join(', ');
  const idadeNum = c.idade ? Number(String(c.idade).replace(/\D/g, '')) : null;
  const moraBP = /paz/i.test(String(c.bairro || ''));

  const expMap = { '0': 'Nunca vendeu o produto', '<1': 'Menos de 1 ano', '1-2': '1 a 2 anos', '2-5': '2 a 5 anos', '>5': 'Mais de 5 anos' };
  const experiencia = expMap[q.exp_tempo] || q.exp_tempo || '';

  const properties = {
    'Candidato': { title: [{ text: { content: nome.slice(0, 2000) } }] },
    'Nível': { select: { name: 'Sênior' } },
    'Vaga': { select: { name: 'Closer / Vendedor Líder' } },
    'Fonte': { select: { name: 'Typebot / formulário' } },
    'Status': { select: { name: 'Triagem' } },
    'Mora no Bairro da Paz': { checkbox: moraBP },
    'Próximo passo': { rich_text: [{ text: { content: 'Revisar candidatura e contatar em até 5 dias úteis' } }] }
  };
  if (c.email) properties['Email'] = { email: String(c.email) };
  if (c.telefone) properties['Telefone'] = { phone_number: String(c.telefone) };
  if (idadeNum) properties['Idade'] = { number: idadeNum };
  if (bairroCidade) properties['Bairro / Cidade'] = { rich_text: [{ text: { content: bairroCidade.slice(0, 2000) } }] };
  if (experiencia) properties['Experiência em vendas'] = { rich_text: [{ text: { content: String(experiencia).slice(0, 2000) } }] };

  const linhas = [
    ['Produtos já vendidos', q.produtos],
    ['Volume (melhor média/mês)', q.volume],
    ['Já vendeu público C/D', q.publico_cd],
    ['Rede de contatos local', q.rede_contatos],
    ['Veículo próprio', q.veiculo],
    ['Resposta ao "já tenho SUS"', r.resposta_sus],
    ['Por que SST Card agora', r.motivo_sst],
    ['Venda em que insistiu 5+ vezes', r.venda_persistiu],
    ['Expectativa de ganho mês 1', r.exp_ganho],
    ['Onde quer estar em 3 anos', r.visao_3anos]
  ];

  const children = [{ object: 'block', type: 'heading_3', heading_3: { rich_text: [{ type: 'text', text: { content: 'Respostas do formulário (Typebot · Sênior)' } }] } }];
  for (const [k, v] of linhas) {
    if (v && String(v).trim()) {
      children.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [
        { type: 'text', text: { content: k + ': ' }, annotations: { bold: true } },
        { type: 'text', text: { content: String(v).slice(0, 1800) } }
      ] } });
    }
  }

  out.push({ json: { parent: { database_id: '8a821b22-4afb-4a42-aa7f-126b8efe7918' }, properties, children } });
}
return out;

// Normaliza o payload do Typebot JÚNIOR (Vendedor Júnior) → corpo da Notion API
