  const idadeNum = c.idade ? Number(String(c.idade).replace(/\D/g, '')) : null;
  // fit local: marca o checkbox se mora no Bairro da Paz (resposta da etapa 4 OU campo bairro)
  const moraBP = /bairro da paz/i.test(String(q.mora_bairro || '')) || /paz/i.test(String(c.bairro || ''));
  const experiencia = q.exp_vendas || '';

  const properties = {
    'Candidato': { title: [{ text: { content: nome.slice(0, 2000) } }] },
