    ['Vez em que convenceu alguém', r.convenceu_alguem],
    ['Quanto quer ganhar/mês', r.exp_ganho],
    ['Onde quer estar em 3 anos', r.sonho_3anos]
  ];

  const children = [{ object: 'block', type: 'heading_3', heading_3: { rich_text: [{ type: 'text', text: { content: 'Respostas do formulário (Typebot · Júnior)' } }] } }];
  for (const [k, v] of linhas) {
    if (v && String(v).trim()) {
      children.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [
        { type: 'text', text: { content: k + ': ' }, annotations: { bold: true } },
        { type: 'text', text: { content: String(v).slice(0, 1800) } }
      ] } });
    }
  }

  out.push({ json: { parent: { database_id: '8a821b22-4afb-4a42-aa7f-126b8efe7918' }, properties, children } });
}
return out;
